package com.menter.treatmentvault.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.menter.treatmentvault.*;import com.menter.treatmentvault.data.*;import kotlinx.coroutines.launch
@Composable fun QuestionScreen(back:()->Unit){val dao=(androidx.compose.ui.platform.LocalContext.current.applicationContext as TreatmentVaultApplication).database.dao();val list by dao.questions().collectAsState(emptyList());val scope=rememberCoroutineScope();var add by remember{mutableStateOf(false)};Page("医生问诊",back){LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){items(list){v->Card{Column(Modifier.padding(12.dp)){Text(v.question,style=MaterialTheme.typography.titleMedium);Text("${v.status} · ${v.date} ${v.doctor}");if(v.answer.isNotBlank())Text("答：${v.answer}")}}};Button({add=true},Modifier.fillMaxWidth()){Text("新增待问")}}
if(add){var q by remember{mutableStateOf("")};var date by remember{mutableStateOf("")};AlertDialog({add=false},{TextButton({if(q.isNotBlank())scope.launch{dao.saveQuestion(QuestionEntity(question=q,date=date));add=false}}){Text("保存")}},dismissButton={TextButton({add=false}){Text("取消")}},title={Text("新增问题")},text={Column{Field(q,{q=it},"问题");Field(date,{date=it},"日期")}})} }
